
const courses = {"easy": [["#######", "#######", "#S...G#", "#######", "#######", "#######", "#######"], ["#######", "#S.F..#", "#####.#", "#####.#", "#####G#", "#######", "#######"], ["#######", "#S.G..#", "###.#.#", "###...#", "#######", "#######", "#######"], ["#######", "#.G#F.#", "#..#S.#", "#.#...#", "#..B..#", "#BF..##", "#######"]], "medium": [["#######", "#.F#GS#", "#F....#", "#....##", "#.#..##", "#.X..B#", "#######"], ["#######", "#...F##", "##S..##", "#..F..#", "#.B...#", "#GB.FX#", "#######"], ["#######", "#..FXG#", "#.#X.B#", "#.#...#", "#.B.F.#", "##.SF.#", "#######"], ["#######", "#X..#F#", "##F...#", "#...B##", "#F...G#", "#BX.FS#", "#######"]], "hard": [["#######", "#B.FX.#", "#..XF.#", "#.#..F#", "#GFS.B#", "#..#..#", "#######"], ["#######", "#FG..##", "#FB...#", "#XBX.S#", "#....F#", "#F.#..#", "#######"], ["#######", "#..XFX#", "#FB.G##", "#SB.F.#", "#F....#", "#.#...#", "#######"]], "impossible": [["#######", "#.FX..#", "##G...#", "#F...##", "#BFS.X#", "#B..F.#", "#######"], ["#######", "#...#F#", "#....F#", "#.FBG##", "#BX.XF#", "#.F..S#", "#######"], ["#######", "#FB#.F#", "#..BFX#", "#XF..F#", "#FG...#", "#.#.SF#", "#######"]]};
const images = ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"].map(src => {const img = new Image(); img.src = src; img.onload = () => draw(); return img;});
const strings = {
 ja:{easy:'イージー',medium:'ミディアム',hard:'ハード',expertHints:['旗に止まれる方向を先に探そう。','お魚を拾ったあと、どう戻るか考えよう。','ひび割れをよけて、最後の一手でぴたっと！'],impossible:'インポッシブル',moves:'手',undo:'ひとつ戻す',reel:'お魚ゲット！',hardHints:['止まるマスを先読みしよう。お魚は4匹！','お魚は5匹。ふわふわ雪と氷の端を使い分けよう。','最難関はお魚7匹。遠回りしてからゴールに戻るルートを探そう。'],title:'ぺんぎん すいーっ', hints:['スワイプで出発。氷の上では雪の壁まで止まれないよ！','お魚を全部拾って、旗のマスでぴたっと止まろう。','通りすぎたら反対側から。旗の先にも氷があるよ！','ふわふわ雪に乗ると、途中でもぴたっと止まるよ。','ひびの氷は、すべりすぎるとドボン！','ふわふわ雪を使って、ひびの氷をよけよう。','お魚を拾う順番を考えてみよう。','最後のコース。どこで止まるか先に考えてみよう！'],level:'ステージ',reset:'やり直す',ready:'氷の上をすいーっ！',play:'あそぶ',next:'つぎへ',clear:'クリア！',finish:'ぜんぶクリア！',again:'もう一度',bump:'ぽふっ！',pass:'あっ、ゴールを通りすぎた！',snow:'雪でぴたっ！',splash:'すべりすぎてドボン！ ひとつ前の場所へ',need:'お魚を全部集めよう！',sound:'音'},
 en:{easy:'Easy',medium:'Medium',hard:'Hard',expertHints:['Work out which direction lets you stop on the flag.','Plan your route back after collecting the fish.','Avoid the cracks and line up your final slide!'],impossible:'Impossible',moves:'moves',undo:'Undo',reel:'Fish caught!',hardHints:['Plan your stops. There are four fish!','Five fish! Use fluffy snow and the edges of the ice.','The hardest course has seven fish. Find the detour that brings you back to the flag.'],title:'Penguin Glide',hints:['Swipe to slide all the way to a snowbank.','Collect every fish and stop on the flag.','Whoops! There is more ice beyond the flag.','Fluffy snow stops your slide right away.','Slide onto cracked ice and… splash!','Use fluffy snow to avoid the cracks.','Try collecting the fish in a different order.','Last course! Plan where each slide will stop.'],level:'Level',reset:'Restart',ready:'Ready to slide?',play:'Play',next:'Next',clear:'Level clear!',finish:'All clear!',again:'Play again',bump:'Poff!',pass:'Whoops! You slid past the flag!',snow:'Stopped in fluffy snow!',splash:'Overshot! Back to your last stop.',need:'Collect every fish first!',sound:'Sound'}
};
const byId = id => document.getElementById(id);
const canvas = byId('rink'), ctx = canvas.getContext('2d');
const dirs = [[-1,0],[0,-1],[0,1],[1,0]];
let language = 'ja';
let courseMoves=0;
let mode='easy', levels=courses.easy, moves=0;
let history=[], catches=[], wake=null;
let index=0, board, player, fish, total, frame=0, motion=false, face=0, flip=false, effect=null, phase='ready', message='', audio=null, sound=false;
const words = () => strings[language];
function startLevel() {
 cancelAnimationFrame(frame);
 board=levels[index]; history=[]; catches=[]; wake=null; moves=0; fish=new Set(); motion=false; face=0; flip=false; effect=null; message='';
 board.forEach((row,y)=>[...row].forEach((tile,x)=>{if(tile==='S')player=[x,y];if(tile==='F')fish.add(y*7+x);}));
 total=fish.size; renderUI(); draw();
}
function renderUI(){
 const t=words(); document.documentElement.lang=language; byId('title').textContent=t.title;
 byId('hint').textContent=({easy:t.hints.slice(0,4),medium:t.hints.slice(4),hard:t.expertHints,impossible:t.hardHints})[mode][index];
 document.querySelectorAll('[data-mode]').forEach(button=>{button.lastElementChild.textContent=t[button.dataset.mode];button.setAttribute('aria-pressed',button.dataset.mode===mode);});
 byId('level').textContent=t.level+' '+(index+1)+' / '+levels.length+' · '+moves+' '+t.moves;
 byId('fish').textContent='🐟 '+(total-fish.size)+' / '+total;
 byId('reset').textContent=t.reset;byId('undo').textContent=t.undo;byId('reset').disabled=phase!=='play';byId('undo').disabled=motion||!history.length||phase!=='play'; byId('sound').textContent=t.sound+(sound?' ♪':' ×');
 byId('sound').setAttribute('aria-pressed',sound); canvas.setAttribute('aria-label',byId('hint').textContent);
 byId('status').textContent=t[message]||'';
 byId('stop').hidden=phase!=='play';byId('advance').textContent={ready:'★ Play',finish:'★ Play again',clear:language==='ja'?'つぎへ':'Next',play:language==='ja'?'プレイ中':'Playing'}[phase];
 byId('advance').disabled=phase==='play';byId('arrows').hidden=phase!=='play';
}
function tile(x,y){return board?.[y]?.[x]||'#';}
function draw(now=performance.now()){
 if(!board)return;
 const unit=96;
 ctx.clearRect(0,0,672,672);
 for(let y=0;y<7;y++)for(let x=0;x<7;x++){
  const cell=tile(x,y), left=x*unit, top=y*unit;
  ctx.fillStyle=cell==='#'?'#9cc7df':cell==='B'?'#e5f7ff':cell==='X'?'#94d6f1':(x+y)%2?'#d5f3ff':'#c7ecfc';
  ctx.fillRect(left,top,unit,unit);
  ctx.strokeStyle='#a7d7eb';ctx.strokeRect(left+.5,top+.5,95,95);
  if(cell==='#'){
   ctx.fillStyle='#f5fcff';ctx.beginPath();ctx.roundRect(left+5,top+5,86,72,20);ctx.fill();
   ctx.fillStyle='#dfedf8';ctx.beginPath();ctx.ellipse(left+45,top+70,34,7,0,0,Math.PI*2);ctx.fill();
  }
  if(cell==='B'||cell==='X'||cell==='G'||fish.has(y*7+x)){
   ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='46px system-ui';
   ctx.fillText(cell==='B'?'❄️':cell==='X'?'💧':cell==='G'?'🏁':'🐟',left+48,top+49);
  }
  if(cell==='X'){
   ctx.strokeStyle='#3f8caf';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(left+13,top+18);ctx.lineTo(left+32,top+34);ctx.lineTo(left+22,top+49);ctx.lineTo(left+33,top+64);ctx.stroke();ctx.lineWidth=1;
  }
 }
 const [x,y]=player;
 const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
 if(wake&&!reduced){
  ctx.fillStyle='#fff';
  for(let i=1;i<=6;i++){
   ctx.globalAlpha=(7-i)/14;
   ctx.beginPath();
   ctx.ellipse((x-wake.dx*i*.14)*unit+48,(y-wake.dy*i*.14)*unit+65+(i%2?7:-7),8-i*.65,3,0,0,Math.PI*2);
   ctx.fill();
  }
  ctx.globalAlpha=1;
 }
 for(const catchFx of catches){
  const age=(now-catchFx.start)/360;
  if(age<0||age>=1)continue;
  ctx.globalAlpha=1-age;ctx.font='bold 29px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#235381';
  ctx.fillText('+1 🐟',catchFx.x*unit+48,catchFx.y*unit+32-(reduced?0:age*27));ctx.globalAlpha=1;
 }
 ctx.save();ctx.translate(x*unit+48,y*unit+50);
 if(effect&&!reduced){
  const t=Math.max(0,Math.min(1,(now-effect.start)/440));
  const bounce=Math.sin(t*Math.PI);
  if(effect.type==='splash'){ctx.translate(0,8*bounce);ctx.rotate(.13*bounce);}
  else if(effect.type==='snow'){ctx.translate(0,-13*bounce);}
  else if(effect.type==='clear'){ctx.translate(0,-24*bounce);ctx.rotate(.18*Math.sin(t*Math.PI*2));}
  else {ctx.rotate(.18*Math.sin(t*Math.PI*4)*(1-t));ctx.scale(1+.12*bounce,1-.12*bounce);}
 }
 if(flip)ctx.scale(-1,1);
 const sprite=images[face];
 if(sprite?.complete&&sprite.naturalWidth)ctx.drawImage(sprite,-44,-44,88,88);
 else {ctx.font='66px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('🐧',0,0);}
 ctx.restore();
 if(effect){
  const age=(now-effect.start)/440;
  if(age<1){
   ctx.globalAlpha=1-age;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 33px system-ui';
   ctx.strokeStyle='#fff';ctx.lineWidth=5;ctx.lineJoin='round';
   const label=effect.type==='splash'?'💦':effect.type==='snow'?'❄️':effect.type==='clear'?'✦ ★ ✦':language==='ja'?'ぽふっ！':'Poff!';
   const px=Math.max(66,Math.min(606,effect.x*unit+48)),py=Math.max(32,effect.y*unit+30-age*39);
   ctx.strokeText(label,px,py);ctx.fillStyle='#285781';ctx.fillText(label,px,py);ctx.globalAlpha=1;ctx.lineWidth=1;
   frame=requestAnimationFrame(draw);
  }else{effect=null;face=0;catches=[];draw(now);}
 }
}
function tone(high){
 if(!sound)return;
 try{
  audio ||= new AudioContext();audio.resume().catch(()=>{});
  const oscillator=audio.createOscillator(), volume=audio.createGain();
  oscillator.type='sine'; oscillator.frequency.setValueAtTime(high?580:250,audio.currentTime);
  oscillator.frequency.exponentialRampToValueAtTime(high?790:125,audio.currentTime+.14);
  volume.gain.setValueAtTime(.075,audio.currentTime);volume.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);
  oscillator.connect(volume).connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+.19);
 }catch{}
}
function slide(dir){
 if(phase!=='play'||motion)return;
 cancelAnimationFrame(frame);effect=null;
 const origin=player.slice(),[dx,dy]=dirs[dir], path=[];
 let [x,y]=origin, outcome='bump';
 while(tile(x+dx,y+dy)!=='#'){
  x+=dx;y+=dy;path.push([x,y]);
  if(tile(x,y)==='X'){outcome='splash';break;}
  if(tile(x,y)==='B'){outcome='snow';break;}
 }
 if(!path.length){face=2;message='bump';effect={x,y,type:'bump',start:performance.now()};tone(false);renderUI();draw();return;}
 history.push({position:origin,fish:new Set(fish),flip});moves++;courseMoves++;motion=true;face=1;wake={dx,dy};catches=[]; if(dx)flip=dx>0;
 message='';renderUI();
 const duration=Math.min(570,170+path.length*65), start=performance.now();
 let visited=0;
 function animate(now){
  const t=Math.min(1,(now-start)/duration), distance=path.length*(t*t*(3-2*t));
  const step=Math.floor(distance), part=distance-step;
  while(visited<step){
   const [fx,fy]=path[visited++];
   if(fish.delete(fy*7+fx)){catches.push({x:fx,y:fy,start:now});tone(true);renderUI();}
  }
  player=[origin[0]+dx*(step+part),origin[1]+dy*(step+part)];
  draw(now);
  if(t<1){frame=requestAnimationFrame(animate);return;}
  motion=false;wake=null;
  const goal=tile(x,y)==='G';
  if(outcome==='splash'){player=origin;message='splash';}
  else if(goal&&!fish.size){phase=index===levels.length-1?'finish':'clear';message='';outcome='clear';tone(true);
   if(phase==='finish')gameScores.finish(Math.max(100,3000-25*courseMoves),true);}
  else if(goal){message='need';}
  else if(path.slice(0,-1).some(([px,py])=>tile(px,py)==='G')){message='pass';}
  else message=outcome;
  face=outcome==='snow'?0:2;effect={x,y,type:outcome,start:now};
  if(phase==='play')tone(false);renderUI();draw(now);
 }
 frame=requestAnimationFrame(animate);
}
byId('advance').onclick=()=>{
 if(phase==='play')return;
 if(phase==='clear')index++;
 else{index=0;courseMoves=0;gameScores.start(mode);}
 phase='play';startLevel();canvas.focus({preventScroll:true});
};
byId('stop').onclick=()=>{gameScores.finish(0,false);phase='finish';startLevel();};
document.querySelectorAll('[data-mode]').forEach(button=>{
 button.onclick=()=>{
  if(mode===button.dataset.mode)return;
  mode=button.dataset.mode;levels=courses[mode];index=0;phase='ready';byId('ready-card').hidden=false;byId('score-card').hidden=true;gameScores.showLevel(mode);startLevel();
 };
});
byId('undo').onclick=()=>{
 if(motion||phase!=='play'||!history.length)return;
 cancelAnimationFrame(frame);
 const previous=history.pop();
 player=previous.position;fish=previous.fish;flip=previous.flip;
 face=0;effect=null;catches=[];message='';renderUI();draw();
};
byId('reset').onclick=()=>{if(phase==='play'){courseMoves+=5;startLevel();}};
byId('sound').onclick=()=>{sound=!sound;tone(true);renderUI();};
momoLanguage.subscribe(code=>{language=code;if(board){renderUI();draw();}});
byId('arrows').onclick=e=>{if(e.target.dataset.dir!==undefined)slide(Number(e.target.dataset.dir));};
window.addEventListener('keydown',e=>{
 const key=['ArrowLeft','ArrowUp','ArrowDown','ArrowRight'].indexOf(e.key);
 if(key>=0&&phase==='play'&&!e.altKey&&!e.metaKey&&!e.ctrlKey){e.preventDefault();if(!e.repeat)slide(key);}
});
let swipe=null;
canvas.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;swipe=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointercancel',()=>{swipe=null;});
canvas.addEventListener('pointerup',e=>{
 if(!swipe||!e.isPrimary)return;
 const dx=e.clientX-swipe[0],dy=e.clientY-swipe[1];swipe=null;
 if(Math.max(Math.abs(dx),Math.abs(dy))>=14)slide(Math.abs(dx)>Math.abs(dy)?(dx>0?3:0):(dy>0?2:1));
});
startLevel();
gameScores.showLevel(mode);
